const STORAGE_KEY = 'rion-marketing-referrers'

export default function ReferrerSeed() {
  const [status, setStatus] = useState('idle') // idle | running | done | error
  const [log, setLog] = useState([])

  function addLog(msg) { setLog(prev => [...prev, msg]) }

  async function runSeed() {
    setStatus('running')
    setLog([])
    try {
      addLog('Loading existing referrers from Supabase...')
      const cloud = await sbLoadMarketing()
      const existing = cloud?.referrers || []
      addLog(`Found ${existing.length} existing referrers in Supabase.`)

      const existingNames = new Set(existing.map(c => (c.name || '').trim().toLowerCase()))
      const toAdd = NEW_CONTACTS.filter(c => !existingNames.has(c.name.trim().toLowerCase()))
      addLog(`New contacts to add: ${toAdd.length} (skipping ${NEW_CONTACTS.length - toAdd.length} already present)`)

      if (toAdd.length === 0) {
        addLog('Nothing to add — all contacts already exist.')
        setStatus('done')
        return
      }

      const merged = [...existing, ...toAdd]
      addLog(`Merged total: ${merged.length} referrers`)

      // Update localStorage so sbSaveMarketing picks it up
      localStorage.setItem(STORAGE_KEY, JSON.stringify(merged))
      addLog('localStorage updated.')

      // Save full payload to Supabase
      const payload = {
        referrers: merged,
        lenders:   (() => { try { return JSON.parse(localStorage.getItem('rion-marketing-lenders') || '[]') } catch { return [] } })(),
        others:    (() => { try { return JSON.parse(localStorage.getItem('rion-marketing-others')   || '[]') } catch { return [] } })(),
        clientOv:  (() => { try { return JSON.parse(localStorage.getItem('rion-marketing-clients')  || '[]') } catch { return [] } })(),
      }
      await sbSaveMarketing(payload)
      addLog(`✅ Supabase updated successfully. Total referrers: ${merged.length}`)
      setStatus('done')
    } catch (err) {
      addLog(`❌ Error: ${err.message}`)
      setStatus('error')
    }
  }

  const C = { navy: '#3D4F6B', pink: '#EB99C2', white: '#fff', bg: '#2A3545', text: '#e8eaf0', muted: '#7A8090', border: '#4a5568' }

  return (
    <div style={{ minHeight: '100vh', background: C.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: 'Montserrat, sans-serif', padding: 24 }}>
      <div style={{ background: C.navy, borderRadius: 12, padding: 40, maxWidth: 600, width: '100%', boxShadow: '0 8px 32px rgba(0,0,0,0.3)' }}>
        <div style={{ fontSize: 22, fontWeight: 700, color: C.white, marginBottom: 8 }}>Referrer Seed Tool</div>
        <div style={{ fontSize: 13, color: C.muted, marginBottom: 28 }}>
          Adds <strong style={{ color: C.pink }}>{NEW_CONTACTS.length} new contacts</strong> to Marketing → Referral Partners without overwriting existing data.
        </div>

        {status === 'idle' && (
          <button onClick={runSeed}
            style={{ background: C.pink, color: '#2A3545', border: 'none', borderRadius: 8, padding: '12px 28px', fontWeight: 700, fontSize: 14, cursor: 'pointer', fontFamily: 'Montserrat, sans-serif' }}>
            Run Import
          </button>
        )}

        {status === 'running' && (
          <div style={{ color: C.muted, fontSize: 13 }}>Running...</div>
        )}

        {log.length > 0 && (
          <div style={{ marginTop: 24, background: '#1a2233', borderRadius: 8, padding: 16 }}>
            {log.map((l, i) => (
              <div key={i} style={{ fontSize: 12, color: l.startsWith('✅') ? C.pink : l.startsWith('❌') ? '#f87171' : C.text, marginBottom: 4 }}>{l}</div>
            ))}
          </div>
        )}

        {status === 'done' && (
          <div style={{ marginTop: 20 }}>
            <div style={{ color: C.pink, fontWeight: 600, marginBottom: 12 }}>Import complete. You can now delete this file from your codebase.</div>
            <a href="/radar/marketing" style={{ color: C.white, fontSize: 13 }}>→ Go to Marketing</a>
          </div>
        )}
      </div>
    </div>
  )
}
